arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_2003_03.json') as f:
    data = json.load(f)

# Look for keys containing AA
def find_aa_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'AA' in k.upper():
                print(f'{path}.{k}')
            find_aa_keys(v, f'{path}.{k}')
    elif isinstance(obj, list) and len(obj) > 0:
        find_aa_keys(obj[0], path)

find_aa_keys(data)
"
